"use server";

import readingTime from "reading-time";
import { BlogPost } from "@/lib/blog-post";
import { revalidatePath } from "next/cache";
import { z } from "zod";

import { auth } from "@/auth";
import { ContactMessage } from "@/lib/contact-message";
import { getPostBySlug, type BlogPostStatus } from "@/lib/mdx";
import dbConnect from "@/lib/mongodb";
import { Subscriber } from "@/lib/subscriber";

const affiliateLinkSchema = z.object({
  label: z.string().trim().min(1),
  url: z.string().trim().url(),
  disclosure: z.string().trim().min(1),
});

const postSaveSchema = z.object({
  originalSlug: z.string().trim().optional(),
  title: z.string().trim().min(3),
  slug: z
    .string()
    .trim()
    .min(3)
    .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  category: z.string().trim().min(1),
  excerpt: z.string().trim().min(10).max(500),
  coverImage: z.string().trim().min(1),
  author: z.string().trim().min(1),
  featured: z.boolean(),
  status: z.enum(["draft", "published", "scheduled"]),
  publishDate: z.string().trim().optional(),
  scheduledAt: z.string().trim().optional(),
  tags: z.array(z.string().trim().min(1)).default([]),
  content: z.string().trim().min(50),
  affiliateLinks: z.array(affiliateLinkSchema).default([]),
}).superRefine((input, ctx) => {
  if (input.status === "scheduled" && !input.scheduledAt?.trim()) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      path: ["scheduledAt"],
      message: "Scheduled posts require a schedule date.",
    });
  }
});

export type PostSaveInput = z.infer<typeof postSaveSchema>;

const subscriberUpdateSchema = z
  .object({
    id: z.string().trim().min(1),
    email: z.string().trim().email(),
    blogUpdates: z.boolean(),
    promotions: z.boolean(),
  })
  .superRefine((input, ctx) => {
    if (!input.blogUpdates && !input.promotions) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["blogUpdates"],
        message: "Select at least one subscription type.",
      });
    }
  });

async function ensureAdmin() {
  const session = await auth();

  if (!session?.user?.email) {
    throw new Error("Unauthorized");
  }

  return session;
}

function slugifyHeading(value: string) {
  return value
    .toLowerCase()
    .trim()
    .replace(/[`~!@#$%^&*()+=,[\]{}|\\:;"'<>,.?/]/g, "")
    .replace(/\s+/g, "-");
}

function extractHeadings(content: string) {
  const headings: {
  id: string;
  text: string;
  level: number;
}[] = [];
  const lines = content.split("\n");

  for (const line of lines) {
    const match = /^(##|###)\s+(.*)$/.exec(line.trim());

    if (!match) continue;

    headings.push({
      id: slugifyHeading(match[2]),
      text: match[2],
      level: match[1].length,
    });
  }

  return headings;
}

function revalidatePostRoutes(slug: string) {
  revalidatePath("/");
  revalidatePath("/blog");
  revalidatePath(`/blog/${slug}`);
  revalidatePath("/blog/[slug]", "page");
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/manage-posts");
  revalidatePath("/admin/new-post");
}

function revalidateSubscriberRoutes() {
  revalidatePath("/admin/subscribers");
}

export async function savePostAction(input: PostSaveInput) {
  await ensureAdmin();

  const parsed = postSaveSchema.safeParse(input);

  if (!parsed.success) {
    throw new Error("Invalid post data.");
  }

  const data = parsed.data;

  await dbConnect();

  const existing = await BlogPost.findOne({
    slug: data.originalSlug ?? data.slug,
  });

  const slugTaken = await BlogPost.findOne({
    slug: data.slug,
    ...(existing ? { _id: { $ne: existing._id } } : {}),
  });

  if (slugTaken) {
    throw new Error("A post with this slug already exists.");
  }

  const scheduledAt = data.scheduledAt
    ? new Date(data.scheduledAt)
    : null;

  if (scheduledAt && Number.isNaN(scheduledAt.getTime())) {
    throw new Error("Invalid schedule date.");
  }

  const manualPublishDate = data.publishDate ? new Date(data.publishDate) : null;

  if (manualPublishDate && Number.isNaN(manualPublishDate.getTime())) {
    throw new Error("Invalid publish date.");
  }

  const publishedAt =
    data.status === "published"
      ? manualPublishDate ?? existing?.publishedAt ?? new Date()
      : data.status === "scheduled"
      ? scheduledAt
      : existing?.publishedAt ?? null;

  const coverImage = data.coverImage.trim();

  const payload = {
    title: data.title,
    slug: data.slug,
    excerpt: data.excerpt,
    content: data.content,
    coverImage,
    author: data.author,
    category: data.category,
    tags: data.tags,
    featured: data.featured,
    status: data.status,
    scheduledAt,
    publishedAt,
    readTime: readingTime(data.content).text,
    headings: extractHeadings(data.content),
    affiliateLinks: data.affiliateLinks,
  };

  if (existing) {
    Object.assign(existing, payload);
    await existing.save();
  } else {
    await BlogPost.create(payload);
  }

  revalidatePostRoutes(data.slug);

  return {
    slug: data.slug,
    status: data.status,
  };
}

export async function deletePostAction(slug: string) {
  await ensureAdmin();

  await dbConnect();

  await BlogPost.deleteOne({
    slug,
  });

  revalidatePostRoutes(slug);
}

export async function togglePostStatusAction(slug: string) {
  await ensureAdmin();

  await dbConnect();

  const post = await BlogPost.findOne({ slug });

  if (!post) {
    throw new Error("Post not found.");
  }

  const isPublishedLike =
    post.status === "published" ||
    (post.status === "scheduled" &&
      post.scheduledAt instanceof Date &&
      post.scheduledAt.getTime() <= Date.now());

  post.status =
    isPublishedLike
      ? "draft"
      : "published";

  if (post.status === "published") {
    post.publishedAt = new Date();
    post.scheduledAt = null;
  } else {
    post.scheduledAt = null;
  }

  await post.save();

  revalidatePostRoutes(slug);
}

export async function markMessageAsReadAction(id: string) {
  await ensureAdmin();
  await dbConnect();
  await ContactMessage.findByIdAndUpdate(id, { status: "read" }).exec();
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/contact-messages");
}

export async function deleteMessageAction(id: string) {
  await ensureAdmin();
  await dbConnect();
  await ContactMessage.findByIdAndDelete(id).exec();
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/contact-messages");
}

export async function deleteMessagesBulkAction(ids: string[]) {
  await ensureAdmin();
  await dbConnect();
  await ContactMessage.deleteMany({ _id: { $in: ids } }).exec();
  revalidatePath("/admin/dashboard");
  revalidatePath("/admin/contact-messages");
}

export async function updateSubscriberAction(
  input: z.infer<typeof subscriberUpdateSchema>,
) {
  await ensureAdmin();

  const parsed = subscriberUpdateSchema.safeParse(input);

  if (!parsed.success) {
    throw new Error("Invalid subscriber data.");
  }

  await dbConnect();

  const data = parsed.data;
  const normalizedEmail = data.email.toLowerCase();
  const existingSubscriber = await Subscriber.findById(data.id);

  if (!existingSubscriber) {
    throw new Error("Subscriber not found.");
  }

  const emailTaken = await Subscriber.findOne({
    email: normalizedEmail,
    _id: { $ne: data.id },
  }).lean();

  if (emailTaken) {
    throw new Error("A subscriber with this email already exists.");
  }

  existingSubscriber.email = normalizedEmail;
  existingSubscriber.blogUpdates = data.blogUpdates;
  existingSubscriber.promotions = data.promotions;

  await existingSubscriber.save();

  revalidateSubscriberRoutes();
}

export async function deleteSubscriberAction(id: string) {
  await ensureAdmin();
  await dbConnect();
  await Subscriber.findByIdAndDelete(id).exec();
  revalidateSubscriberRoutes();
}

export async function deleteSubscribersBulkAction(ids: string[]) {
  await ensureAdmin();
  await dbConnect();
  await Subscriber.deleteMany({ _id: { $in: ids } }).exec();
  revalidateSubscriberRoutes();
}

"use client";

import { useEffect, useMemo, useState } from "react";
import useEmblaCarousel from "embla-carousel-react";
import { ChevronLeft, ChevronRight, Download, X } from "lucide-react";

import type { GalleryPinItem } from "@/lib/gallery-types";
import { cn } from "@/lib/utils";

type GalleryLightboxProps = {
  pin: GalleryPinItem;
  initialIndex?: number;
  onClose(): void;
};

export function GalleryLightbox({
  pin,
  initialIndex = 0,
  onClose,
}: GalleryLightboxProps) {
  const [selectedIndex, setSelectedIndex] = useState(initialIndex);
  const [emblaRef, emblaApi] = useEmblaCarousel({
    loop: pin.images.length > 1,
    startIndex: initialIndex,
  });

  useEffect(() => {
    document.body.style.overflow = "hidden";

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        onClose();
      }
    }

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      document.body.style.overflow = "";
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [onClose]);

  useEffect(() => {
    if (!emblaApi) {
      return;
    }


    const onSelect = () => {
      setSelectedIndex(emblaApi.selectedScrollSnap());
    };

    emblaApi.on("select", onSelect);
    emblaApi.scrollTo(initialIndex, true);

    return () => {
      emblaApi.off("select", onSelect);
    };
  }, [emblaApi, initialIndex]);

  const currentImage = useMemo(() => {
    return pin.images[selectedIndex] ?? pin.images[0];
  }, [pin.images, selectedIndex]);

  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center bg-black/88 px-3 py-3 backdrop-blur-[2px] sm:px-4 sm:py-4"
      onClick={onClose}
    >
      <div
        className="relative flex h-full max-h-[94vh] w-full max-w-[1400px] flex-col overflow-hidden rounded-[28px] border border-white/8 bg-[#05080f] shadow-[0_30px_120px_rgba(0,0,0,0.45)]"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="grid min-h-0 flex-1 lg:grid-cols-[minmax(0,1fr)_320px] xl:grid-cols-[minmax(0,1fr)_340px]">
          <div className="relative min-h-0 bg-black">
            <div className="h-full overflow-hidden" ref={emblaRef}>
              <div className="flex h-full">
                {pin.images.map((imageUrl, index) => (
                  <div key={`${imageUrl}-${index}`} className="min-w-0 shrink-0 grow-0 basis-full">
                    <div className="flex h-full items-center justify-center px-4 py-6 sm:px-6 sm:py-8">
                      <img
                        src={imageUrl}
                        alt={`${pin.title} image ${index + 1}`}
                        className="max-h-[78vh] w-auto max-w-full rounded-[22px] object-contain shadow-[0_20px_80px_rgba(0,0,0,0.35)]"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {pin.images.length > 1 ? (
              <>
                <button
                  type="button"
                  onClick={() => emblaApi?.scrollPrev()}
                  className="absolute left-3 top-1/2 inline-flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-black/55 text-white transition-colors hover:bg-black/75 sm:left-4"
                >
                  <ChevronLeft className="h-5 w-5" />
                </button>
                <button
                  type="button"
                  onClick={() => emblaApi?.scrollNext()}
                  className="absolute right-3 top-1/2 inline-flex h-11 w-11 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-black/55 text-white transition-colors hover:bg-black/75 sm:right-4"
                >
                  <ChevronRight className="h-5 w-5" />
                </button>
              </>
            ) : null}
          </div>

          <aside className="relative flex min-h-0 flex-col border-t border-white/10 bg-[#081428] lg:border-l lg:border-t-0">
            <button
              type="button"
              onClick={onClose}
              className="absolute right-4 top-4 z-10 inline-flex h-11 w-11 items-center justify-center rounded-full border border-white/10 bg-black/20 text-white transition-colors hover:bg-black/35"
            >
              <X className="h-5 w-5" />
            </button>

            <div className="space-y-5 p-6 pr-20">
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.24em] text-white/45">
                  Gallery Pin
                </p>
                <h2 className="mt-3 text-2xl font-semibold leading-tight text-white">
                  {pin.title}
                </h2>
              </div>

              {pin.description ? (
                <p className="text-sm leading-7 text-white/70">{pin.description}</p>
              ) : (
                <p className="text-sm leading-7 text-white/45">
                  No description was added for this gallery pin.
                </p>
              )}

              <a
                href={currentImage}
                download
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center justify-center gap-2 rounded-full bg-primary px-5 py-3 text-sm font-semibold text-white shadow-[0_10px_30px_rgba(15,110,86,0.25)] transition-colors hover:bg-primary/90"
              >
                <Download className="h-4 w-4" />
                Download
              </a>

              <div className="rounded-2xl border border-white/8 bg-white/[0.03] px-4 py-3 text-xs uppercase tracking-[0.18em] text-white/45">
                {selectedIndex + 1} / {pin.images.length} Images
              </div>
            </div>

            {pin.images.length > 1 ? (
              <div className="grid grid-cols-4 gap-3 border-t border-white/10 p-4">
                {pin.images.map((imageUrl, index) => (
                  <button
                    key={`${imageUrl}-thumb-${index}`}
                    type="button"
                    onClick={() => emblaApi?.scrollTo(index)}
                    className={cn(
                      "overflow-hidden rounded-2xl border bg-[#0d1d36] transition-all",
                      selectedIndex === index
                        ? "border-primary ring-2 ring-primary/30"
                        : "border-white/10 hover:border-white/30",
                    )}
                  >
                    <img
                      src={imageUrl}
                      alt={`${pin.title} thumbnail ${index + 1}`}
                      className="h-20 w-full object-cover"
                    />
                  </button>
                ))}
              </div>
            ) : null}
          </aside>
        </div>

        {pin.images.length > 1 ? (
          <div className="flex items-center justify-center gap-2 border-t border-white/10 bg-[#06101f] px-6 py-4">
            {pin.images.map((_, index) => (
              <button
                key={index}
                type="button"
                onClick={() => emblaApi?.scrollTo(index)}
                className={cn(
                  "h-2.5 w-2.5 rounded-full transition-colors",
                  selectedIndex === index ? "bg-primary" : "bg-white/20 hover:bg-white/35",
                )}
              />
            ))}
          </div>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { AdUnit } from "@/components/ads/AdUnit";
import type { GalleryPinItem } from "@/lib/gallery-types";

type GalleryMasonryProps = {
  pins: GalleryPinItem[];
  onSelect(pin: GalleryPinItem): void;
  showInlineAds: boolean;
};

type GalleryRenderableItem =
  | { type: "pin"; pin: GalleryPinItem }
  | { type: "ad"; key: string };

function buildRenderableItems(
  pins: GalleryPinItem[],
  showInlineAds: boolean,
): GalleryRenderableItem[] {
  if (!showInlineAds) {
    return pins.map((pin) => ({ type: "pin", pin }));
  }

  const items: GalleryRenderableItem[] = [];

  pins.forEach((pin, index) => {
    items.push({ type: "pin", pin });

    if ((index + 1) % 9 === 0) {
      items.push({
        type: "ad",
        key: `gallery-grid-${index}`,
      });
    }
  });

  return items;
}

export function GalleryMasonry({
  pins,
  onSelect,
  showInlineAds,
}: GalleryMasonryProps) {
  const items = buildRenderableItems(pins, showInlineAds);

  return (
    <div className="columns-2 gap-4 md:columns-3 lg:columns-4 xl:columns-5">
      {items.map((item, index) =>
        item.type === "ad" ? (
          <div
            key={item.key}
            className="mb-4 break-inside-avoid overflow-hidden rounded-[24px] border border-black/6 bg-white p-3 shadow-sm"
          >
            <div className="mb-3 px-1 text-xs font-semibold uppercase tracking-[0.18em] text-text/40">
              Sponsored
            </div>
            <AdUnit slot="gallery-grid" format="rectangle" />
          </div>
        ) : (
          <button
            key={item.pin.id}
            type="button"
            onClick={() => onSelect(item.pin)}
            className="group relative mb-4 block w-full break-inside-avoid overflow-hidden rounded-[24px] border border-black/6 bg-white text-left shadow-sm transition-transform hover:-translate-y-1"
          >
            <img
              src={item.pin.images[0]}
              alt={item.pin.title}
              loading={index < 10 ? "eager" : "lazy"}
              className="h-auto w-full object-cover transition-transform duration-300 group-hover:scale-[1.03]"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/65 via-black/10 to-transparent opacity-90 transition-opacity group-hover:opacity-100" />
            <div className="absolute inset-x-0 bottom-0 p-4">
              <h3 className="line-clamp-2 text-sm font-semibold text-white sm:text-base">
                {item.pin.title}
              </h3>
            </div>
          </button>
        ),
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { ImageUp, LoaderCircle, Upload, X } from "lucide-react";

import { GalleryToast } from "@/components/gallery/GalleryToast";
import { cn } from "@/lib/utils";

type LocalImageFile = {
  id: string;
  file: File;
  previewUrl: string;
};

type ToastState =
  | {
      type: "success" | "error";
      message: string;
    }
  | null;

function createLocalImageFile(file: File) {
  return {
    id: `${file.name}-${file.lastModified}-${Math.random().toString(36).slice(2, 8)}`,
    file,
    previewUrl: URL.createObjectURL(file),
  };
}

export function GalleryUploadForm() {
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [files, setFiles] = useState<LocalImageFile[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toast, setToast] = useState<ToastState>(null);

  useEffect(() => {
    return () => {
      for (const item of files) {
        URL.revokeObjectURL(item.previewUrl);
      }
    };
  }, [files]);

  const canSubmit = useMemo(() => {
    return Boolean(title.trim()) && files.length > 0 && !isSubmitting;
  }, [files.length, isSubmitting, title]);

  function appendFiles(nextFiles: FileList | File[]) {
    const imageFiles = Array.from(nextFiles).filter((file) => file.type.startsWith("image/"));

    if (!imageFiles.length) {
      setToast({
        type: "error",
        message: "Please select image files only.",
      });
      return;
    }

    setFiles((current) => [...current, ...imageFiles.map(createLocalImageFile)]);
  }

  function removeFile(id: string) {
    setFiles((current) => {
      const fileToRemove = current.find((item) => item.id === id);

      if (fileToRemove) {
        URL.revokeObjectURL(fileToRemove.previewUrl);
      }

      return current.filter((item) => item.id !== id);
    });
  }

  function resetForm() {
    for (const item of files) {
      URL.revokeObjectURL(item.previewUrl);
    }

    setTitle("");
    setDescription("");
    setFiles([]);

    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!title.trim()) {
      setToast({
        type: "error",
        message: "Title is required.",
      });
      return;
    }

    if (!files.length) {
      setToast({
        type: "error",
        message: "Add at least one image before publishing.",
      });
      return;
    }

    try {
      setIsSubmitting(true);
      setToast(null);

      const uploadFormData = new FormData();

      for (const item of files) {
        uploadFormData.append("files", item.file);
      }

      const uploadResponse = await fetch("/api/gallery/upload", {
        method: "POST",
        body: uploadFormData,
      });

      const uploadPayload = (await uploadResponse.json()) as {
        error?: string;
        urls?: string[];
      };

      if (!uploadResponse.ok || !uploadPayload.urls?.length) {
        throw new Error(uploadPayload.error ?? "Unable to upload images.");
      }

      const createResponse = await fetch("/api/gallery/pins", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          title,
          description,
          images: uploadPayload.urls,
        }),
      });

      const createPayload = (await createResponse.json()) as { error?: string; message?: string };

      if (!createResponse.ok) {
        throw new Error(createPayload.error ?? "Unable to publish gallery pin.");
      }

      resetForm();
      setToast({
        type: "success",
        message: createPayload.message ?? "Gallery pin published successfully.",
      });
    } catch (error) {
      setToast({
        type: "error",
        message:
          error instanceof Error
            ? error.message
            : "Unable to publish gallery pin right now.",
      });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <>
      {toast ? (
        <GalleryToast
          type={toast.type}
          message={toast.message}
          onClose={() => setToast(null)}
        />
      ) : null}

      <form onSubmit={handleSubmit} className="space-y-8">
        <div className="grid gap-8 xl:grid-cols-[1.2fr_0.8fr]">
          <div className="space-y-6">
            <div
              role="button"
              tabIndex={0}
              onClick={() => fileInputRef.current?.click()}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  fileInputRef.current?.click();
                }
              }}
              onDragOver={(event) => {
                event.preventDefault();
                setIsDragging(true);
              }}
              onDragLeave={(event) => {
                event.preventDefault();
                setIsDragging(false);
              }}
              onDrop={(event) => {
                event.preventDefault();
                setIsDragging(false);
                appendFiles(event.dataTransfer.files);
              }}
              className={cn(
                "rounded-[28px] border border-dashed bg-[#f5f7fb] p-8 transition-colors",
                isDragging ? "border-primary/40 bg-primary/5" : "border-black/10",
              )}
            >
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                multiple
                className="hidden"
                onChange={(event) => {
                  if (event.target.files) {
                    appendFiles(event.target.files);
                  }
                }}
              />

              <div className="flex min-h-[280px] flex-col items-center justify-center gap-5 text-center">
                <div className="flex h-16 w-16 items-center justify-center rounded-full bg-white text-primary shadow-sm">
                  <Upload className="h-7 w-7" />
                </div>
                <div className="space-y-2">
                  <p className="text-base font-medium text-slate-900">
                    Choose a file or drag and drop it here
                  </p>
                  <p className="text-sm text-slate-500">
                    Upload multiple images for one gallery pin. First image becomes the cover.
                  </p>
                </div>
              </div>
            </div>

            {files.length ? (
              <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4">
                {files.map((item) => (
                  <div
                    key={item.id}
