                  className="min-h-[240px] w-full rounded-[24px] border border-black/8 bg-[#fbfcfd] px-4 py-4 font-mono text-sm leading-7 text-slate-800 outline-none transition-shadow focus:ring-4 focus:ring-primary/10"
